using Atomic.Elements;using Atomic.Entities;namespace Game.Gameplay{    public static class WeaponUseCase    {        public static bool CanAttackWithWeapon(this IGameEntity character)        {            IWeaponEntity weapon = character.GetValue(GameEntityAPI.Weapon).Value;            ICommand command = weapon?.GetValue(WeaponEntityAPI.AttackCommand);            return weapon != null && command.CanInvoke();        }        public static void AttackWithWeapon(this IGameEntity character)        {            IWeaponEntity weapon = character.GetValue(GameEntityAPI.Weapon).Value;            ICommand command = weapon?.GetValue(WeaponEntityAPI.AttackCommand);            command?.Invoke();        }                public static bool CollectAmmoWithWeapon(this IGameEntity character, int amount)        {            HaveWeaponWithAmmo(character);            IWeaponEntity weapon = character.GetValue(GameEntityAPI.Weapon).Value;            IReactiveVariable<int> ammo = weapon.GetValue(WeaponEntityAPI.Ammo);            ammo.Value += amount;            return true;        }        public static bool HaveWeaponWithAmmo(this IGameEntity character) =>            character.TryGetValue(GameEntityAPI.Weapon, out IVariable<IWeaponEntity> weaponVariable) &&            weaponVariable.Value != null &&            weaponVariable.Value.TryGetValue(WeaponEntityAPI.Ammo, out IReactiveVariable<int> _);    }}